#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 200001

typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* adj[MAXV];
int color[MAXV];
int count[2];
int V, E;

void addEdge(int u, int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = adj[u];
    adj[u] = newNode;

    newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = u;
    newNode->next = adj[v];
    adj[v] = newNode;
}

int dfs(int u, int c) {
    color[u] = c;
    count[c]++;
    Node* temp = adj[u];
    while (temp) {
        int v = temp->vertex;
        if (color[v] == -1) {
            if (!dfs(v, 1 - c)) return 0;
        } else if (color[v] == c) {
            return 0;
        }
        temp = temp->next;
    }
    return 1;
}

int main() {
    scanf("%d %d", &V, &E);
    for (int i = 1; i <= V; i++) {
        adj[i] = NULL;
        color[i] = -1;
    }
    for (int i = 0; i < E; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        addEdge(u, v);
    }

    long long maxEdges = 0;
    for (int i = 1; i <= V; i++) {
        if (color[i] == -1) {
            count[0] = 0;
            count[1] = 0;
            if (!dfs(i, 0)) {
                printf("-1\n");
                // free memory (optional in contest)
                return 0;
            }
            maxEdges += (long long)count[0] * count[1];
        }
    }

    long long ans = maxEdges - E;
    printf("%lld\n", ans);
    return 0;
}

