#define MAXV 1005

int color[MAXV];
int adj[MAXV][MAXV];
int V, E;

int main() {
    scanf("%d %d", &V, &E);
    memset(adj, 0, sizeof(adj));
    memset(color, -1, sizeof(color));

    for (int i = 0; i < E; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    // BFS 2-coloring
    int queue[MAXV];
    int cnt[2]; // sizes per component
    // dp[j] = 1 if achievable
    int dp[MAXV];
    memset(dp, 0, sizeof(dp));
    dp[0] = 1;

    int bipartite = 1;

    for (int start = 0; start < V && bipartite; start++) {
        if (color[start] != -1) continue;
        color[start] = 0;
        int head = 0, tail = 0;
        queue[tail++] = start;
        cnt[0] = 1; cnt[1] = 0;
        int ok = 1;
        while (head < tail) {
            int u = queue[head++];
            for (int w = 0; w < V; w++) {
                if (adj[u][w]) {
                    if (color[w] == -1) {
                        color[w] = 1 - color[u];
                        cnt[color[w]]++;
                        queue[tail++] = w;
                    } else if (color[w] == color[u]) {
                        ok = 0;
                    }
                }
            }
        }
        if (!ok) { bipartite = 0; break; }
        // Update DP
        int ndp[MAXV];
        memset(ndp, 0, sizeof(ndp));
        for (int j = 0; j <= V; j++) {
            if (!dp[j]) continue;
            if (j + cnt[0] <= V) ndp[j + cnt[0]] = 1;
            if (j + cnt[1] <= V) ndp[j + cnt[1]] = 1;
        }
        memcpy(dp, ndp, sizeof(dp));
    }

    if (!bipartite) { printf("-1\n"); return 0; }

    long long best = 0;
    for (int j = 0; j <= V; j++) {
        if (dp[j]) {
            long long val = (long long)j * (V - j);
            if (val > best) best = val;
        }
    }

    printf("%lld\n", best - E);
    return 0;
}

