typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;

    Edge *edges = (Edge *)malloc((2LL * E) * sizeof(Edge));
    int *head = (int *)malloc((V + 1) * sizeof(int));
    int *color = (int *)malloc((V + 1) * sizeof(int));
    int *queue = (int *)malloc((V + 5) * sizeof(int));

    for (int i = 1; i <= V; i++) {
        head[i] = -1;
        color[i] = -1;
    }

    int idx = 0;
    for (int i = 0; i < E; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[idx].to = v;
        edges[idx].next = head[u];
        head[u] = idx++;

        edges[idx].to = u;
        edges[idx].next = head[v];
        head[v] = idx++;
    }

    int bipartite = 1;
    ll maxEdges = 0;

    for (int s = 1; s <= V; s++) {
        if (color[s] != -1) continue;

        int front = 0, back = 0;
        queue[back++] = s;
        color[s] = 0;

        ll cnt[2] = {1, 0};

        while (front < back) {
            int u = queue[front++];
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    cnt[color[v]]++;
                    queue[back++] = v;
                } else if (color[v] == color[u]) {
                    bipartite = 0;
                }
            }
        }

        maxEdges += cnt[0] * cnt[1];
    }

    if (!bipartite) {
        printf("-1\n");
    } else {
        printf("%lld\n", maxEdges - E);
    }

    free(edges);
    free(head);
    free(color);
    free(queue);
    return 0;
}

