    bool bipartite = true;
    vector<pair<int,int>> components;

    for(int i = 0; i < V && bipartite; i++){
        if(color[i] == -1){
            queue<int> q;
            q.push(i);
            color[i] = 0;
            int cnt[2] = {0,0};
            while(!q.empty() && bipartite){
                int u = q.front(); q.pop();
                cnt[color[u]]++;
                for(int w : adj[u]){
                    if(color[w] == -1){
                        color[w] = 1 - color[u];
                        q.push(w);
                    } else if(color[w] == color[u]){
                        bipartite = false;
                    }
                }
            }
            if(bipartite) components.push_back({cnt[0], cnt[1]});
        }
    }

    if(!bipartite){ cout << -1 << endl; return 0; }

    // DP
    vector<bool> dp(V+1, false);
    dp[0] = true;
    for(auto [a,b] : components){
        vector<bool> ndp(V+1, false);
        for(int j = 0; j <= V; j++){
            if(!dp[j]) continue;
            if(j+a <= V) ndp[j+a] = true;
            if(j+b <= V) ndp[j+b] = true;
        }
        dp = ndp;
    }

    long long ans = 0;
    for(int j = 0; j <= V; j++){
        if(dp[j]) ans = max(ans, (long long)j*(V-j));
    }

    cout << ans - E << endl;
    return 0;
