            if (color[i] == -1) {
                Queue<Integer> q = new LinkedList<>();
                q.add(i); color[i] = 0;
                int c0 = 0, c1 = 0;
                while (!q.isEmpty() && bipartite) {
                    int u = q.poll();
                    if (color[u] == 0) c0++; else c1++;
                    for (int w : adj.get(u)) {
                        if (color[w] == -1) { color[w] = 1 - color[u]; q.add(w); }
                        else if (color[w] == color[u]) bipartite = false;
                    }
                }
                components.add(new int[]{c0, c1});
            }
        }
        if (!bipartite) { System.out.println(-1); return; }
        boolean[] dp = new boolean[V + 1];
        dp[0] = true;
        for (int[] comp : components) {
            boolean[] ndp = new boolean[V + 1];
