        }
        System.out.println(best - E);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static List<Integer>[] g;
    static int[] color;
    static boolean isBipartite = true;
    static long part0, part1;

    static void dfs(int start) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        color[start] = 0;
        part0++;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : g[u]) {
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    if (color[v] == 0) part0++;
                    else part1++;
                    stack.push(v);
                } else if (color[v] == color[u]) {
                    isBipartite = false;
                    return;
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int V = fs.nextInt();
        int E = fs.nextInt();

        g = new ArrayList[V];
        for (int i = 0; i < V; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < E; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        color = new int[V];
        Arrays.fill(color, -1);

        long maxEdges = 0;

        for (int i = 0; i < V; i++) {
            if (color[i] == -1) {
                part0 = 0;
                part1 = 0;
                dfs(i);
                if (!isBipartite) {
                    System.out.println(-1);
                    return;
                }
                maxEdges += part0 * part1;
            }
        }

        long answer = maxEdges - E;
        System.out.println(answer);
    }
}
